#!/usr/bin/env python3
"""
Comprehensive test of the Azure B2C client ID scope fix.
"""

import sys
import os
sys.path.insert(0, os.path.join(os.path.dirname(__file__), 'msal'))

from msal.application import ClientApplication
from tests.http_client import MinimalHttpClient


class MockAuthority:
    """Mock authority for testing without HTTP calls"""
    def __init__(self, is_b2c=False):
        self._is_b2c = is_b2c
        self.is_adfs = False


def test_non_b2c_behavior_preserved():
    """Ensure non-B2C behavior is unchanged"""
    print("=== Testing Non-B2C Behavior Preservation ===")

    client_id = "test-client-id"
    app = ClientApplication(client_id=client_id, validate_authority=False)
    app.authority = MockAuthority(is_b2c=False)

    # Test 1: Only client ID should be replaced with reserved scopes
    try:
        scopes = [client_id]
        decorated = app._decorate_scope(scopes)
        expected = {'openid', 'profile', 'offline_access'}
        actual = set(decorated)
        if actual == expected:
            print("✓ Single client ID correctly replaced with reserved scopes")
        else:
            print(f"✗ Incorrect replacement. Expected: {expected}, Got: {actual}")
    except Exception as e:
        print(f"✗ Error: {e}")

    # Test 2: Reserved scopes in input should be rejected
    try:
        scopes = ["openid", "custom_scope"]
        decorated = app._decorate_scope(scopes)
        print("✗ Reserved scopes should have been rejected")
    except ValueError as e:
        if "API does not accept" in str(e):
            print("✓ Reserved scopes correctly rejected")
        else:
            print(f"✗ Wrong error: {e}")
    except Exception as e:
        print(f"✗ Unexpected error: {e}")

    # Test 3: Client ID with other scopes should be rejected
    try:
        scopes = [client_id, "custom_scope"]
        decorated = app._decorate_scope(scopes)
        print("✗ Mixed client ID scopes should have been rejected")
    except ValueError as e:
        if "Client Id can only be provided as a single scope" in str(e):
            print("✓ Mixed client ID scopes correctly rejected")
        else:
            print(f"✗ Wrong error: {e}")
    except Exception as e:
        print(f"✗ Unexpected error: {e}")


def test_b2c_behavior_fixed():
    """Test that B2C behavior is now correct"""
    print("\n=== Testing B2C Behavior Fix ===")

    client_id = "test-client-id"
    app = ClientApplication(client_id=client_id, validate_authority=False)
    app.authority = MockAuthority(is_b2c=True)

    # Test 1: Only client ID should be preserved (not replaced)
    try:
        scopes = [client_id]
        decorated = app._decorate_scope(scopes)
        if client_id in decorated and len(decorated) > 3:  # Should include reserved + client_id
            print("✓ Single client ID preserved for B2C")
            print(f"  Decorated scopes: {sorted(decorated)}")
        else:
            print(f"✗ Client ID not properly preserved: {decorated}")
    except Exception as e:
        print(f"✗ Error: {e}")

    # Test 2: Azure B2C documented pattern should work
    try:
        scopes = ["openid", "offline_access", client_id]
        decorated = app._decorate_scope(scopes)
        expected_elements = {"openid", "offline_access", client_id, "profile"}
        actual_set = set(decorated)

        if client_id in actual_set:
            print("✓ Azure B2C pattern works correctly")
            print(f"  Input: {scopes}")
            print(f"  Output: {sorted(decorated)}")
        else:
            print(f"✗ Client ID missing from result: {actual_set}")
    except Exception as e:
        print(f"✗ Error with B2C pattern: {e}")

    # Test 3: Custom scopes with B2C should work
    try:
        scopes = ["custom_scope"]
        decorated = app._decorate_scope(scopes)
        if "custom_scope" in decorated and set(['openid', 'profile', 'offline_access']).issubset(set(decorated)):
            print("✓ Custom scopes work correctly with B2C")
        else:
            print(f"✗ Custom scopes not handled properly: {decorated}")
    except Exception as e:
        print(f"✗ Error with custom scopes: {e}")


def test_edge_cases():
    """Test edge cases"""
    print("\n=== Testing Edge Cases ===")

    client_id = "test-client-id"
    app = ClientApplication(client_id=client_id, validate_authority=False)
    app.authority = MockAuthority(is_b2c=True)

    # Test with empty scopes
    try:
        scopes = []
        decorated = app._decorate_scope(scopes)
        expected = {'openid', 'profile', 'offline_access'}
        if set(decorated) == expected:
            print("✓ Empty scopes handled correctly")
        else:
            print(f"✗ Empty scopes issue: {decorated}")
    except Exception as e:
        print(f"✗ Error with empty scopes: {e}")

    # Test duplicate handling
    try:
        scopes = [client_id, client_id]  # duplicates
        decorated = app._decorate_scope(scopes)
        if client_id in decorated:
            print("✓ Duplicate scopes handled correctly")
        else:
            print(f"✗ Duplicate handling issue: {decorated}")
    except Exception as e:
        print(f"✗ Error with duplicates: {e}")


if __name__ == "__main__":
    test_non_b2c_behavior_preserved()
    test_b2c_behavior_fixed()
    test_edge_cases()
